use std::collections::BTreeMap;

use harness_strategy_sdk::serde_json::Value;
use harness_strategy_sdk::{
    export_screening_program, ScreenContext, ScreenRow, ScreeningProgram,
};

// fca-screener-rows: [{"kind":"avg_dollar_volume_min","params":{"min":"250000000"}},{"kind":"price_min","params":{"min":"20"}}]

struct UiScreener;

impl ScreeningProgram for UiScreener {
    fn new(_parameters: Value) -> Self {
        Self
    }

    fn screen(&mut self, ctx: &ScreenContext) -> Vec<ScreenRow> {
        let mut rows = Vec::new();
        for symbol in ctx.universe().iter() {
            let bars = ctx.bars(symbol);
            let mut metrics = BTreeMap::new();
            if let Some(bar) = bars.last() {
                metrics.insert("close".to_string(), bar.close.clone());
            }
            // filter: avg $vol >= 250,000,000
            {
                let mut dollar_volume_total = 0.0_f64;
                let mut dollar_volume_count = 0_u64;
                for entry in bars.iter() {
                    if let (Ok(close), Ok(volume)) = (entry.close.parse::<f64>(), entry.volume.parse::<f64>()) {
                        dollar_volume_total += close * volume;
                        dollar_volume_count += 1;
                    }
                }
                if dollar_volume_count == 0 { continue; }
                let avg_dollar_volume = dollar_volume_total / dollar_volume_count as f64;
                if !(avg_dollar_volume >= 250000000.0) { continue; }
                metrics.insert("avg_dollar_volume".to_string(), format!("{avg_dollar_volume:.4}"));
            }
            // filter: price >= $20
            {
                let Some(bar) = bars.last() else { continue; };
                let Ok(close) = bar.close.parse::<f64>() else { continue; };
                if !(close >= 20.0) { continue; }
                metrics.insert("close".to_string(), bar.close.clone());
            }

            rows.push(ScreenRow {
                symbol: symbol.clone(),
                metrics,
            });
        }
        rows
    }
}

export_screening_program!(UiScreener);

use std::collections::BTreeMap;

use harness_strategy_sdk::serde_json::Value;
use harness_strategy_sdk::{
    export_screening_program, ScreenContext, ScreenRow, ScreeningProgram,
};

// fca-screener-rows: [{"kind":"rsi_below","params":{"period":"14","threshold":"30"}},{"kind":"fundamentals_min","params":{"field":"revenue","min":"1000000000"}}]

struct UiScreener;

impl ScreeningProgram for UiScreener {
    fn new(_parameters: Value) -> Self {
        Self
    }

    fn screen(&mut self, ctx: &ScreenContext) -> Vec<ScreenRow> {
        let mut rows = Vec::new();
        for symbol in ctx.universe().iter() {
            let bars = ctx.bars(symbol);
            let facts = ctx.facts(symbol);
            let mut metrics = BTreeMap::new();
            if let Some(bar) = bars.last() {
                metrics.insert("close".to_string(), bar.close.clone());
            }
            // filter: RSI(14) <= 30
            {
                if bars.len() <= 14 { continue; }
                let mut rsi_gain = 0.0_f64;
                let mut rsi_loss = 0.0_f64;
                let mut rsi_count = 0_u64;
                for window in bars.windows(2).rev().take(14) {
                    if let (Ok(previous), Ok(current)) = (window[0].close.parse::<f64>(), window[1].close.parse::<f64>()) {
                        let change = current - previous;
                        if change >= 0.0 { rsi_gain += change; } else { rsi_loss -= change; }
                        rsi_count += 1;
                    }
                }
                if rsi_count == 0 { continue; }
                let rsi_14 = if rsi_loss == 0.0 && rsi_gain == 0.0 { 50.0 } else if rsi_loss == 0.0 { 100.0 } else {
                    100.0 - 100.0 / (1.0 + (rsi_gain / rsi_count as f64) / (rsi_loss / rsi_count as f64))
                };
                if !(rsi_14 <= 30.0) { continue; }
                metrics.insert("ind:rsi(period=14)".to_string(), format!("{rsi_14:.6}"));
            }
            // filter: fundamentals.revenue >= 1,000,000,000
            {
                let Some(fact) = facts.get("revenue") else { continue; };
                let Ok(number) = fact.trim().parse::<f64>() else { continue; };
                if !(number >= 1000000000.0) { continue; }
                metrics.insert("revenue".to_string(), fact.clone());
            }

            rows.push(ScreenRow {
                symbol: symbol.clone(),
                metrics,
            });
        }
        rows
    }
}

export_screening_program!(UiScreener);

use std::collections::BTreeMap;

use harness_strategy_sdk::serde_json::Value;
use harness_strategy_sdk::{
    export_screening_program, ScreenContext, ScreenRow, ScreeningProgram,
};

// fca-screener-rows: [{"kind":"momentum_min","params":{"period":"20","min":"5"}},{"kind":"price_above_sma","params":{"period":"50"}}]

struct UiScreener;

impl ScreeningProgram for UiScreener {
    fn new(_parameters: Value) -> Self {
        Self
    }

    fn screen(&mut self, ctx: &ScreenContext) -> Vec<ScreenRow> {
        let mut rows = Vec::new();
        for symbol in ctx.universe().iter() {
            let bars = ctx.bars(symbol);
            let mut metrics = BTreeMap::new();
            if let Some(bar) = bars.last() {
                metrics.insert("close".to_string(), bar.close.clone());
            }
            // filter: momentum(20d) >= 5%
            {
                let Some(bar) = bars.last() else { continue; };
                let Ok(close) = bar.close.parse::<f64>() else { continue; };
                if bars.len() <= 20 { continue; }
                let Ok(past) = bars[bars.len() - 1 - 20].close.parse::<f64>() else { continue; };
                if !(past > 0.0) { continue; }
                let momentum_20d = (close / past - 1.0) * 100.0;
                if !(momentum_20d >= 5.0) { continue; }
                metrics.insert("momentum_20d".to_string(), format!("{momentum_20d:.6}"));
            }
            // filter: price >= SMA(50)
            {
                let Some(bar) = bars.last() else { continue; };
                let Ok(close) = bar.close.parse::<f64>() else { continue; };
                let mut sma_total = 0.0_f64;
                let mut sma_count = 0_u64;
                for entry in bars.iter().rev().take(50) {
                    if let Ok(value) = entry.close.parse::<f64>() {
                        sma_total += value;
                        sma_count += 1;
                    }
                }
                if sma_count == 0 { continue; }
                let sma = sma_total / sma_count as f64;
                if !(close >= sma) { continue; }
                metrics.insert("close".to_string(), bar.close.clone());
                metrics.insert("ind:sma(period=50)".to_string(), format!("{sma:.6}"));
            }

            rows.push(ScreenRow {
                symbol: symbol.clone(),
                metrics,
            });
        }
        rows
    }
}

export_screening_program!(UiScreener);
